inline std::uint32_t ex_first_convert(binary_float::Number n){return binary_float::truncate(binary_float::rounded(n,0,53));}
inline void update_ex_first_enemy(std::uint32_t behavior,Enemy& e,std::uint32_t index,ProjectilePools& pool,const ObjectRecord<240>& player,PatternParameters& p,Random& random,RandomPrecision precision,GameMath& math,ExFirstServices& services){
 using namespace ex_first_detail;const Arithmetic m{static_cast<unsigned>(precision)};const auto q=[&](std::size_t o){return m.q(e.quad(o));};const auto put=[&](std::size_t o,binary_float::Number v){e.quad(o,m.store(v));};const auto age=[&](){return signed_word(e.word(12));};const auto value=[&](std::size_t o){return crt_sse2::real(e.quad(o));};const auto c=[](std::uint32_t a){return crt_sse2::real(constant(a));};
 const auto emit_at=[&](std::uint32_t kind,std::int32_t group,std::array<std::uint32_t,3> rgb,std::uint32_t blend,std::uint64_t x,std::uint64_t y,std::uint32_t count,std::uint64_t spacing,std::uint64_t speed,std::uint64_t angle,std::uint32_t absolute,std::uint32_t config){ex_first_emit(pool,{{kind,group,rgb,blend,255,1,41},x,y,count,spacing,speed,angle,absolute,config},player,p,random,precision,math);};
 const auto emit=[&](std::uint32_t kind,std::int32_t group,std::array<std::uint32_t,3> rgb,std::uint32_t blend,std::uint32_t count,std::uint64_t spacing,std::uint64_t speed,std::uint64_t angle,std::uint32_t absolute,std::uint32_t config){const auto y=e.quad(64),x=e.quad(56);emit_at(kind,group,rgb,blend,x,y,count,spacing,speed,angle,absolute,config);};
 if(behavior==118){if(age()<=90){ex_first_ease(e,56,e.quad(72),constant(0x6d1e20),m.precision);ex_first_ease(e,64,e.quad(80),constant(0x6d1e20),m.precision);}
  else if(age()<=1350){if(remainder(e.word(12),60)==0){auto angle=m.store(m.mul(random.real_number(constant(0x6d1c60),precision),m.c(0x6d1950)));const auto dx=m.store(m.sub(m.q(player.quad(144)),q(56))),dy=m.store(m.sub(m.q(player.quad(152)),q(64)));const auto target=m.store(math.atan2(dy,dx));const bool large=e.word(4)==4;p.integers[0]=20;p.integers[1]=large?60u:40u;for(unsigned i=0;i<(large?32u:24u);++i){auto v=math.sine(angle);const auto y=m.store(m.add(m.mul(v,m.c(large?0x6d1aa8:0x6d1e78)),q(64)));v=math.cosine(angle);const auto x=m.store(m.add(m.mul(v,m.c(large?0x6d1aa8:0x6d1e78)),q(56)));emit_at(9,0,large?std::array<std::uint32_t,3>{{255,180,0}}:std::array<std::uint32_t,3>{{0,255,180}},2,x,y,1,0,constant(large?0x6d1ff8:0x6d1948),target,1,2);angle=m.store(m.add(m.q(angle),m.c(large?0x6d1ba0:0x6d2198)));}}}
  else if(e.word(12)==1500){e.word(20,0);services.kill_enemy(index);}return;
 }
 if(behavior==119){if(age()<=60){ex_first_ease(e,64,constant(0x6b25f8),constant(0x6d1a40),m.precision);return;}if(remainder(e.word(12),4)==0&&value(168)<c(0x6d1b78)){const bool red=e.word(4)==4;const auto green=ex_first_convert(m.mul(m.div(q(168),m.c(0x6d2168)),m.c(0x6a7eb8)));const auto slot=allocate_projectile(pool,{4,0,{{red?255u:0u,green,red?0u:255u}},0,255,1,41});if(slot!=-1){auto& b=pool.bullets[slot];b.quad(64,e.quad(56));b.quad(72,e.quad(168));b.word(8,108);b.quad(104,0);b.quad(160,constant(0x6d2130));b.quad(96,e.quad(176));}put(176,m.add(q(176),q(184)));put(168,m.add(q(168),m.c(0x6d1a40)));}put(64,m.sub(q(64),m.c(0x6d1fb8)));if(value(64)<c(0x6d19f0))e.word(0,0);return;}
 if(behavior==120||behavior==121){const bool right=behavior==121;put(56,right?m.sub(q(56),q(176)):m.add(q(56),q(176)));put(64,m.add(m.add(m.c(0x6d19c0),q(168)),q(64)));put(168,m.mul(q(168),m.c(0x6d1970)));if(age()<=80)put(176,m.sub(q(176),m.c(0x6d2828)));else if(age()<=244){put(176,m.add(q(176),m.c(0x6d29c0)));put(168,m.sub(q(168),m.c(0x6d1928)));}else{put(176,m.add(q(176),q(184)));put(184,m.mul(q(184),m.c(0x6d1c38)));put(168,m.add(q(168),m.c(0x6d1a08)));}
  if(age()<(right?18:16))return;if(right)put(192,m.add(q(192),q(200)));const auto rem=remainder(e.word(12),e.word(128));if(rem==(right?0:17)&&(right?value(56)<=c(0x6d20e8):value(56)>=c(0x6d1898))){const auto color=ex_first_convert(m.mul(m.div(q(56),m.c(0x6d1cb0)),m.c(0x6a7eb8)));if(right){const auto v=math.sine(e.quad(192));const auto angle=m.store(m.mul(v,q(208)));emit(3,0,{{255u-color,0,color}},0,5,constant(0x6d2618),constant(0x6d1ce0),angle,1,1);}else emit(10,0,{{color,0,255u-color}},0,13,constant(0x6d2008),constant(0x6d2548),0,0,1);}if(right?value(56)>c(0x6d19e8):value(56)<c(0x6d19f0))e.word(0,0);return;
 }
 if(behavior==122){auto v=math.cosine(e.quad(168));put(56,m.add(m.mul(v,q(184)),q(192)));v=math.sine(e.quad(168));put(64,m.add(m.mul(v,q(184)),q(200)));put(168,m.add(q(168),q(176)));if(remainder(e.word(12),40)==0&&value(56)>0.&&value(56)<c(0x6d1cb0)&&value(64)>0.&&value(64)<c(0x6d19a0)){p.integers[0]=0;const bool type2=e.word(4)==2;for(unsigned j=0;j<3;++j){p.integers[1]=j*10u+1;emit(16,0,type2?std::array<std::uint32_t,3>{{j*60u,180,0}}:std::array<std::uint32_t,3>{{180,j*60u,0}},0,3,constant(0x6d18b0),constant(0x6d1ad8),0,0,2);}}if(age()>signed_word(e.word(128)))e.word(0,0);return;}
 if(behavior==123){const auto v=math.cosine(e.quad(168));put(56,m.add(m.mul(v,m.c(0x6d1a90)),m.c(0x6d1a60)));put(168,m.add(q(168),m.c(0x6d2510)));if(age()<=80)ex_first_ease(e,64,constant(0x6d1cc0),constant(0x6d1a90),m.precision);else if(age()<=720){ex_first_ease(e,64,constant(0x6d1fe8),constant(0x6d1a90),m.precision);if(remainder(e.word(12),35)==0){emit(2,1,{{90,0,255}},2,3,constant(0x6d2750),constant(0x6d26e0),e.quad(176),1,0);const auto angle=m.store(m.add(q(176),m.c(0x6d1860)));emit(2,1,{{255,0,90}},2,3,constant(0x6d2750),constant(0x6d26e0),angle,1,0);put(176,m.sub(q(176),m.c(0x6d29b8)));}}else{put(64,m.add(q(64),m.c(0x6d1c18)));if(value(64)>c(0x6d1d68))e.word(0,0);}return;}
 if(behavior==124){put(56,m.add(q(56),q(168)));put(168,m.add(q(168),q(176)));ex_first_ease(e,64,constant(0x6d1fb0),constant(0x6d1a40),m.precision);if(value(56)>0.&&value(56)<c(0x6d1cb0)){const auto rem=remainder(e.word(12),20);if(rem==0||rem==3||rem==6)emit(0,2,{{0,255,0}},0,1,0,constant(0x6d1ce0),constant(value(64)<=crt_sse2::real(player.quad(152))?0x6d1b60:0x6d1de0),1,0);}if(value(56)<c(0x6d1b58)||value(56)>c(0x6d1bb8))e.word(0,0);return;}
 throw std::out_of_range("EX first enemy outside118..124");
}
